// refs: [{ book, ch, page }] — printed page numbers. Empty = general knowledge (not in the books).
export const FACTS = [
  {"unit": 0, "title": "Atoms, electrons and charge", "body": "All matter is built from atoms: a nucleus of positive protons and neutral neutrons, surrounded by negative electrons. Normally the counts balance. Add or remove electrons and the atom becomes a charged ion. Like charges repel; unlike charges attract.", "formula": "e ≈ 1.6×10⁻¹⁹ C per electron; 1 C ≈ 6.24×10¹⁸ electrons", "example": "A plastic rod picks up 1.25×10¹⁹ extra electrons. Its charge is 1.25×10¹⁹ × 1.6×10⁻¹⁹ = 2 C, and it is negative because electrons were added.", "refs": [{"book": "gibilisco", "ch": 1, "page": 3}, {"book": "hughes", "ch": 2, "page": 15}]},
  {"unit": 0, "title": "Conductors, insulators, semiconductors", "body": "In a conductor (silver, copper, aluminium) electrons hop easily from atom to atom. In an insulator (glass, plastic) they barely move. Semiconductors like silicon sit in between, and adding impurities (doping) lets us control them, which is what makes diodes, transistors and ICs possible.", "formula": "Conductor: many free electrons; insulator: few; semiconductor: tunable", "example": "Same size rods (1 m long, 1 mm²) at 0.1 V: copper (≈0.017 Ω) passes ≈5.9 A; glass (≈10¹⁸ Ω) passes ≈10⁻¹⁹ A, which is effectively nothing.", "refs": [{"book": "gibilisco", "ch": 1, "page": 11}, {"book": "gibilisco", "ch": 1, "page": 14}]},
  {"unit": 0, "title": "Current: the flow of charge", "body": "Current is how much charge passes a point each second. It only flows if there is a complete loop and something pushing it. By convention, current flows from + to − outside the source, even though electrons actually drift the other way.", "formula": "I = Q ÷ t   (1 A = 1 C/s)", "example": "30 C passes through a wire in 6 s. I = 30 ÷ 6 = 5 A. In 1 minute at the same current, 5 × 60 = 300 C would pass.", "refs": [{"book": "hughes", "ch": 2, "page": 16}, {"book": "gibilisco", "ch": 1, "page": 15}]},
  {"unit": 0, "title": "Voltage: EMF and potential difference", "body": "Voltage is energy per unit of charge. EMF (E) is the energy a source gives each coulomb; potential difference (p.d., V) is the energy each coulomb gives up between two points, e.g. across a load. Both are measured in volts. Voltage is the push; current is the flow.", "formula": "V = W ÷ Q   (1 V = 1 J/C)", "example": "A 12 V battery moves 5 C of charge round a circuit. Energy delivered W = V × Q = 12 × 5 = 60 J.", "refs": [{"book": "hughes", "ch": 2, "page": 16}, {"book": "gibilisco", "ch": 2, "page": 23}]},
  {"unit": 0, "title": "Resistance and the ohm", "body": "Resistance is how strongly a material opposes current. Higher resistance means less current for the same voltage. One ohm is the resistance that lets 1 A flow when 1 V is applied. Resistance turns electrical energy into heat.", "formula": "R = V ÷ I   (1 Ω = 1 V/A)", "example": "A part has 9 V across it and draws 0.03 A. R = 9 ÷ 0.03 = 300 Ω.", "refs": [{"book": "gibilisco", "ch": 2, "page": 26}, {"book": "hughes", "ch": 2, "page": 19}]},
  {"unit": 0, "title": "Conductance and the siemens", "body": "Conductance is the flip side of resistance: how easily current flows. It is just 1 divided by resistance, measured in siemens (S). It is handy for parallel circuits, where conductances simply add.", "formula": "G = 1 ÷ R   (siemens, S)", "example": "A 250 Ω resistor has G = 1 ÷ 250 = 0.004 S = 4 mS. A wire with G = 0.5 S has R = 1 ÷ 0.5 = 2 Ω.", "refs": [{"book": "gibilisco", "ch": 2, "page": 28}]},
  {"unit": 0, "title": "Ohm's law", "body": "For many conductors at constant temperature, the voltage across them is directly proportional to the current through them. The ratio is the resistance. Always work in volts, amps and ohms (convert mA, kΩ first) or the answer will be off by powers of ten.", "formula": "V = I × R   →   I = V ÷ R,   R = V ÷ I", "example": "5 V across a 2.2 kΩ resistor: I = 5 ÷ 2200 = 0.00227 A ≈ 2.27 mA. Double the voltage to 10 V and the current doubles to ≈4.55 mA.", "refs": [{"book": "hughes", "ch": 2, "page": 20}, {"book": "gibilisco", "ch": 4, "page": 69}]},
  {"unit": 0, "title": "Power and the watt", "body": "Power is the rate at which energy is used or delivered. One watt is one joule per second. In a resistor all of that power becomes heat. Using Ohm's law, power can be written three ways, so pick the one that fits the values you know.", "formula": "P = V × I = I²R = V² ÷ R", "example": "A 12 V lamp draws 0.5 A: P = 12 × 0.5 = 6 W. A 100 Ω resistor carrying 0.2 A: P = 0.2² × 100 = 4 W.", "refs": [{"book": "hughes", "ch": 3, "page": 49}, {"book": "gibilisco", "ch": 2, "page": 29}]},
  {"unit": 0, "title": "Energy: joules and kilowatt-hours", "body": "Energy is power multiplied by time. The SI unit is the joule (1 W for 1 s). That is tiny, so electricity bills use the kilowatt-hour: 1 kW running for 1 hour. Power is how fast; energy is how much in total.", "formula": "W = P × t;   1 kWh = 1000 W × 3600 s = 3.6 MJ", "example": "A 1.5 kW heater runs for 2 h: W = 1.5 × 2 = 3 kWh = 3 × 3.6 = 10.8 MJ. At ₹8 per unit, it costs 3 × 8 = ₹24.", "refs": [{"book": "hughes", "ch": 3, "page": 51}, {"book": "gibilisco", "ch": 2, "page": 31}]},
  {"unit": 0, "title": "SI units and prefixes", "body": "SI is the international, coherent system of units: base units like the metre, second and ampere combine neatly into derived ones like the volt and ohm. Prefixes scale a unit by powers of ten so we can write 4.7 kΩ or 250 μA instead of long strings of zeros.", "formula": "p=10⁻¹² n=10⁻⁹ μ=10⁻⁶ m=10⁻³ k=10³ M=10⁶ G=10⁹", "example": "250 μA flows through 4.7 kΩ. Convert: 250×10⁻⁶ A and 4.7×10³ Ω. V = 0.00025 × 4700 = 1.175 V.", "refs": [{"book": "hughes", "ch": 1, "page": 4}, {"book": "gibilisco", "ch": 2, "page": 31}]},
  {"unit": 0, "title": "Resistivity: what sets a wire's R", "body": "A wire's resistance grows with its length and shrinks as it gets thicker. The material sets the constant: resistivity ρ, in ohm metres. Copper has a low ρ, which is why it is used for wiring; alloys like manganin have a much higher ρ.", "formula": "R = ρ × l ÷ A", "example": "20 m of copper wire, area 0.5 mm² (0.5×10⁻⁶ m²), ρ = 1.7×10⁻⁸ Ω m: R = 1.7×10⁻⁸ × 20 ÷ (0.5×10⁻⁶) = 0.68 Ω.", "refs": [{"book": "hughes", "ch": 3, "page": 52}, {"book": "hughes", "ch": 3, "page": 53}]},
  {"unit": 0, "title": "Resistance changes with temperature", "body": "Pure metals gain resistance as they heat up; carbon, electrolytes and insulators lose it. Over a moderate range the change is roughly proportional to the temperature rise. The temperature coefficient α tells you how much per degree.", "formula": "R_θ = R₀(1 + α₀θ);   copper α₀ ≈ 0.0043 /°C", "example": "A copper coil is 100 Ω at 0 °C. At 50 °C: R = 100 × (1 + 0.0043 × 50) = 100 × 1.215 = 121.5 Ω.", "refs": [{"book": "hughes", "ch": 3, "page": 54}]},
  {"unit": 0, "title": "Resistors in series", "body": "In series, parts sit one after another, so the same current flows through all of them. The total resistance is just the sum, and the supply voltage is shared out in proportion to each resistance. If one part opens, everything stops.", "formula": "R = R₁ + R₂ + R₃;   V = V₁ + V₂ + V₃", "example": "100 Ω + 220 Ω + 680 Ω = 1000 Ω on 10 V: I = 10 mA. Drops: 1 V, 2.2 V and 6.8 V, which add back to 10 V.", "refs": [{"book": "hughes", "ch": 3, "page": 31}, {"book": "gibilisco", "ch": 4, "page": 73}]},
  {"unit": 0, "title": "Resistors in parallel", "body": "In parallel, every part sits across the same two points, so each gets the full voltage. Currents add up, and the combined resistance is always smaller than the smallest branch. Adding branches lowers it further.", "formula": "1/R = 1/R₁ + 1/R₂ + …;   two: R = R₁R₂ ÷ (R₁ + R₂)", "example": "6 Ω ∥ 3 Ω = (6×3) ÷ (6+3) = 2 Ω. On 12 V: 2 A in the 6 Ω, 4 A in the 3 Ω, 6 A total = 12 ÷ 2.", "refs": [{"book": "hughes", "ch": 3, "page": 36}, {"book": "gibilisco", "ch": 4, "page": 74}]},
  {"unit": 0, "title": "Series-parallel circuits", "body": "Most real circuits mix series and parallel parts. Solve them by shrinking the network step by step: combine each obvious series or parallel group into one resistor until only one is left, find the total current, then work back out to each part.", "formula": "Reduce inner groups first, then expand back out with Ohm's law", "example": "4 Ω in series with (12 Ω ∥ 6 Ω = 4 Ω): total 8 Ω. On 24 V, I = 3 A. The pair gets 3 × 4 = 12 V: 1 A in 12 Ω, 2 A in 6 Ω.", "refs": [{"book": "gibilisco", "ch": 4, "page": 75}, {"book": "hughes", "ch": 3, "page": 45}]},
  {"unit": 0, "title": "Kirchhoff's current law (KCL)", "body": "Charge cannot pile up at a junction, so whatever current flows in must flow out. Treat currents into a node as positive and out as negative, and their sum is zero. A negative answer just means the real current runs the other way.", "formula": "ΣI at a node = 0   (total in = total out)", "example": "5 A enters a node. Two branches carry 2 A and 1.2 A away. Third branch: 5 − 2 − 1.2 = 1.8 A, also leaving the node.", "refs": [{"book": "hughes", "ch": 3, "page": 42}, {"book": "gibilisco", "ch": 5, "page": 89}]},
  {"unit": 0, "title": "Kirchhoff's voltage law (KVL)", "body": "Go round any closed loop and you end up at the same potential you started from. So the EMFs pushing round the loop must equal the voltage drops across the parts in it. It is energy conservation for circuits.", "formula": "ΣE = ΣIR around any closed loop", "example": "A 12 V battery feeds three resistors in series. Two show 3 V and 5 V. The third must drop 12 − 3 − 5 = 4 V.", "refs": [{"book": "hughes", "ch": 3, "page": 46}, {"book": "gibilisco", "ch": 5, "page": 91}]},
  {"unit": 0, "title": "The voltage divider", "body": "Two resistors in series split the supply in the ratio of their values. It is the most common way to make a lower voltage or bias point. A load connected across the output sits in parallel with R₂ and pulls the output down, so keep the divider current about 10× the load current.", "formula": "V_out = V_in × R₂ ÷ (R₁ + R₂)", "example": "12 V, R₁ = 10 kΩ, R₂ = 5 kΩ: V_out = 12 × 5 ÷ 15 = 4 V. Add a 5 kΩ load: R₂ ∥ load = 2.5 kΩ, so V_out = 12 × 2.5 ÷ 12.5 = 2.4 V.", "refs": [{"book": "bishop", "ch": 3, "page": 25}, {"book": "hughes", "ch": 3, "page": 35}]},
  {"unit": 0, "title": "The current divider", "body": "When current splits between two parallel resistors, more goes through the smaller one. The share in one branch is set by the OTHER resistor divided by the sum. Equal resistors share equally.", "formula": "I₁ = I × R₂ ÷ (R₁ + R₂)", "example": "6 A splits between 10 Ω and 20 Ω. I(10 Ω) = 6 × 20 ÷ 30 = 4 A; I(20 Ω) = 6 × 10 ÷ 30 = 2 A. Check: 4 + 2 = 6 A.", "refs": [{"book": "hughes", "ch": 3, "page": 40}]},
  {"unit": 0, "title": "Resistor types and tolerance", "body": "Common types: carbon composition (cheap), carbon or metal film (accurate, low noise), wirewound (high power and precise, but acts a bit like an inductor) and tiny IC resistors. Tolerance tells you how far the real value may sit from the marked one.", "formula": "Actual R lies within R_nominal × (1 ± tolerance)", "example": "A 680 Ω ±10 % resistor may be anywhere from 680 − 68 = 612 Ω to 680 + 68 = 748 Ω. At ±1 % the range shrinks to 673.2–686.8 Ω.", "refs": [{"book": "gibilisco", "ch": 6, "page": 102}, {"book": "gibilisco", "ch": 6, "page": 110}]},
  {"unit": 0, "title": "The resistor colour code", "body": "Bands give the value: the first two are digits, the third is a multiplier (how many zeros). A fourth band shows tolerance. Digits run Black 0, Brown 1, Red 2, Orange 3, Yellow 4, Green 5, Blue 6, Violet 7, Grey 8, White 9.", "formula": "R = d₁d₂ × 10^n; gold ±5 %, silver ±10 %, none ±20 %", "example": "Red-red-orange-gold: 2, 2, × 1000 = 22 kΩ ±5 %. True value can be 20.9 kΩ to 23.1 kΩ.", "refs": [{"book": "gibilisco", "ch": 6, "page": 112}, {"book": "hughes", "ch": 2, "page": 23}]},
  {"unit": 0, "title": "Potentiometers and rheostats", "body": "A potentiometer is a resistive track with a sliding wiper on a third terminal, so it works as an adjustable voltage divider. Tracks can be linear or audio (log) taper. A rheostat is a wirewound variable resistor for high-power current control; it adjusts in small steps, one turn at a time.", "formula": "Linear pot: V_wiper = V × (fraction of track below wiper)", "example": "A 10 kΩ linear pot across 5 V with the wiper 30 % up: 3 kΩ below, 7 kΩ above, so V_wiper = 5 × 0.3 = 1.5 V.", "refs": [{"book": "gibilisco", "ch": 6, "page": 105}, {"book": "gibilisco", "ch": 6, "page": 109}]},
  {"unit": 0, "title": "Power rating of a resistor", "body": "Every resistor heats up when current flows, and the power rating is the most it can shed without damage. Always pick a rating comfortably above the real dissipation; a 10 % or larger margin is good practice.", "formula": "P = I²R = V²/R must be < rating;   I_max = √(P ÷ R)", "example": "220 Ω across 9 V: P = 81 ÷ 220 ≈ 0.37 W. A ¼ W part would overheat, so use ½ W or more. Max current in a ¼ W 470 Ω: √(0.25 ÷ 470) ≈ 23 mA.", "refs": [{"book": "gibilisco", "ch": 6, "page": 110}, {"book": "hughes", "ch": 2, "page": 22}]},
  {"unit": 0, "title": "The decibel", "body": "Our ears (and many systems) respond to ratios, not differences, so we compare powers on a log scale. Positive dB means a gain, negative means a loss. +3 dB is double the power, +10 dB is ten times, −3 dB is half.", "formula": "dB = 10 log₁₀(P₂ ÷ P₁)", "example": "An amplifier turns 2 mW into 200 mW: ratio 100, so dB = 10 × log 100 = 10 × 2 = 20 dB. Halving power: 10 × log 0.5 ≈ −3 dB.", "refs": [{"book": "gibilisco", "ch": 6, "page": 107}]},
  {"unit": 0, "title": "Cells and batteries", "body": "A cell turns chemical energy into electrical energy. Primary cells (zinc-carbon, alkaline) are used once and thrown away. Secondary cells (lead-acid, NiCd, Li-ion) can be recharged. A battery is several cells joined together. Capacity is given in ampere-hours.", "formula": "Energy (Wh) = Ah × V;   run time ≈ capacity ÷ current", "example": "A 2000 mAh, 3.7 V cell stores 2 × 3.7 = 7.4 Wh. Drawing 250 mA, it lasts about 2000 ÷ 250 = 8 h.", "refs": [{"book": "gibilisco", "ch": 7, "page": 119}, {"book": "gibilisco", "ch": 7, "page": 121}]},
  {"unit": 0, "title": "Internal resistance of a source", "body": "Every real source has some resistance inside it. When current flows, part of the EMF is lost across this internal resistance, so the terminal voltage falls as the load gets heavier. That is why a weak battery sags under load.", "formula": "V_terminal = E − I × r", "example": "E = 12 V, r = 0.5 Ω, load 5.5 Ω: I = 12 ÷ (5.5 + 0.5) = 2 A. Terminal voltage = 12 − 2 × 0.5 = 11 V.", "refs": [{"book": "hughes", "ch": 4, "page": 69}, {"book": "gibilisco", "ch": 7, "page": 121}]},
  {"unit": 0, "title": "Thévenin's theorem", "body": "Any two-terminal network of sources and resistors can be replaced by one EMF in series with one resistor. E_Th is the open-circuit voltage at the terminals; R_Th is the resistance seen there with sources replaced by their internal resistances.", "formula": "I_load = E_Th ÷ (R_Th + R_L)", "example": "12 V source, 6 Ω on top, 3 Ω below; output across 3 Ω. E_Th = 12 × 3 ÷ 9 = 4 V; R_Th = 6 ∥ 3 = 2 Ω. With a 2 Ω load: I = 4 ÷ 4 = 1 A.", "refs": [{"book": "hughes", "ch": 4, "page": 77}]},
  {"unit": 0, "title": "Norton's theorem", "body": "Norton is Thévenin's twin: the same network becomes a constant-current source in parallel with a resistor. I_N is the current that flows if you short the terminals; R_N is the same resistance as R_Th. Pick whichever makes the maths easier.", "formula": "I_N = I_short-circuit = E_Th ÷ R_Th;   R_N = R_Th", "example": "Same circuit as Thévenin: shorting the output gives I_N = 12 ÷ 6 = 2 A, R_N = 2 Ω. A 2 Ω load takes half: 2 × 2 ÷ (2 + 2) = 1 A. Same answer.", "refs": [{"book": "hughes", "ch": 4, "page": 84}, {"book": "hughes", "ch": 4, "page": 81}]},
  {"unit": 0, "title": "Superposition", "body": "With several sources, find the effect of each one alone (replacing the others by their internal resistance, i.e. a short for an ideal voltage source) and add the results. It works for currents and voltages in linear circuits, not for power.", "formula": "I_total = I(source 1 alone) + I(source 2 alone) + …", "example": "12 V (4 Ω) and 6 V (4 Ω) sources both feed a 2 Ω load. 12 V alone: 1.5 A in load. 6 V alone: 0.75 A. Together: 1.5 + 0.75 = 2.25 A (4.5 V across load).", "refs": [{"book": "hughes", "ch": 4, "page": 75}]},
  {"unit": 0, "title": "Maximum power transfer", "body": "A source delivers the most power to a load when the load resistance equals the source's internal resistance. At that point half the power is wasted inside the source (50 % efficiency), so it is used in signal circuits, not power supplies.", "formula": "Max power when R_L = r;   P_max = E² ÷ 4r", "example": "E = 10 V, r = 5 Ω. R_L = 5 Ω: I = 1 A, P = 1² × 5 = 5 W (= 100 ÷ 20). R_L = 10 Ω: I ≈ 0.667 A, P ≈ 4.44 W, which is less.", "refs": [{"book": "hughes", "ch": 4, "page": 88}]},
  {"unit": 1, "title": "What a capacitor is", "body": "A capacitor is two conducting plates kept apart by an insulator called the dielectric. Connected to a DC source, electrons pile up on one plate and leave the other, so it stores charge, and keeps it after you disconnect. Current flows only while it charges; steady DC is then blocked.", "formula": "Two plates + insulator: stores charge, blocks steady DC", "example": "Close a switch linking 9 V, 1 MΩ and a capacitor: current jumps to 9 μA (9 V ÷ 1 MΩ), then dies away to 0 as the capacitor voltage climbs to 9 V. Remove the battery and a meter still reads about 9 V across it.", "refs": [{"book": "hughes", "ch": 5, "page": 93}, {"book": "bishop", "ch": 4, "page": 31}]},
  {"unit": 1, "title": "Capacitance: Q = CV", "body": "Capacitance tells you how much charge a capacitor holds for each volt across its plates. One farad means 1 coulomb per volt, which is huge, so real parts are rated in μF, nF or pF. Double the voltage and the stored charge doubles too.", "formula": "Q = C × V   (1 F = 1 C/V; 1 μF = 10⁻⁶ F, 1 pF = 10⁻¹² F)", "example": "A 47 μF capacitor on a 12 V rail holds Q = 47×10⁻⁶ × 12 = 564 μC. At 24 V it would hold twice that, 1128 μC.", "refs": [{"book": "hughes", "ch": 5, "page": 95}, {"book": "bishop", "ch": 4, "page": 31}]},
  {"unit": 1, "title": "What sets capacitance", "body": "Bigger plates hold more charge, and plates closer together hold more, so C grows with area and shrinks with gap. Filling the gap with a dielectric multiplies C by its relative permittivity εr (air ≈ 1, glass 5–10). Thinner gaps raise C but lower the voltage the part can stand.", "formula": "C = ε₀ × εr × A ÷ d   (ε₀ = 8.85×10⁻¹² F/m)", "example": "Plates 10 cm × 10 cm (A = 0.01 m²), gap 0.1 mm, εr = 5: C = 8.85×10⁻¹² × 5 × 0.01 ÷ 0.0001 ≈ 4.4 nF. Halve the gap and C doubles to ≈ 8.9 nF.", "refs": [{"book": "hughes", "ch": 5, "page": 98}, {"book": "hughes", "ch": 5, "page": 101}]},
  {"unit": 1, "title": "Capacitors in parallel and series", "body": "In parallel, capacitors share the same voltage and it is like adding plate area, so values simply add. In series, each carries the same charge and the gap effectively grows, so the total is smaller than the smallest one. These rules are the mirror image of the resistor rules.", "formula": "Parallel: C = C₁ + C₂ …   Series: 1/C = 1/C₁ + 1/C₂ …", "example": "10 μF and 15 μF in parallel: 25 μF. In series: 1/C = 1/10 + 1/15 = 0.1667, so C = 6 μF (same as 10×15 ÷ 25). Across 30 V in series, the 10 μF gets 18 V and the 15 μF gets 12 V.", "refs": [{"book": "hughes", "ch": 5, "page": 96}, {"book": "gibilisco", "ch": 11, "page": 202}]},
  {"unit": 1, "title": "Charging a capacitor: RC time constant", "body": "Charging through a resistor is not instant. At first all the supply voltage sits across R, so current is V/R; as the capacitor fills, current falls and its voltage rises ever more slowly. The time constant RC sets the pace: 63% after one RC, practically full after about five.", "formula": "τ = R × C;   v = V(1 − e^(−t/RC))", "example": "R = 10 kΩ, C = 100 μF, so τ = 10 000 × 0.0001 = 1 s. On a 5 V supply: after 1 s v ≈ 0.632 × 5 = 3.16 V; after 5 s v ≈ 4.97 V (99.3%). Start current = 5 V ÷ 10 kΩ = 0.5 mA.", "refs": [{"book": "hughes", "ch": 5, "page": 107}, {"book": "bishop", "ch": 4, "page": 36}]},
  {"unit": 1, "title": "Energy stored in a capacitor", "body": "Pushing charge onto a capacitor takes work, and that energy is held in the electric field between the plates until it is discharged. Energy grows with the square of voltage, which is why big, high-voltage capacitors can give a dangerous shock even after power is off.", "formula": "W = ½ C V² = Q² ÷ (2C)   joules", "example": "1000 μF at 25 V: W = 0.5 × 0.001 × 25² = 0.3125 J ≈ 0.31 J. Charge the same part to 50 V and W = 1.25 J, four times as much.", "refs": [{"book": "hughes", "ch": 5, "page": 119}]},
  {"unit": 1, "title": "Capacitor types", "body": "Ceramic: small values (pF to about 1 μF), cheap and tiny, great for decoupling. Film (polyester, polypropylene): stable and low-leakage, good for timing and filters. Electrolytic (aluminium, tantalum): very large values in a small case, but polarised, wide tolerance and leakier.", "formula": "Small/fast: ceramic · stable: film · bulk μF: electrolytic", "example": "A logic board might use a 100 nF ceramic at each IC supply pin, a 10 nF film part in a timer, and a 2200 μF electrolytic rated 35 V on a 24 V rail, fitted with the − lead to ground.", "refs": [{"book": "bishop", "ch": 4, "page": 32}, {"book": "gibilisco", "ch": 11, "page": 206}]},
  {"unit": 1, "title": "Magnetism and magnetic fields", "body": "A magnet has a north and a south pole. Its field is pictured as flux lines that leave N, curve round to S, and close back through the magnet; they never cross. Like poles repel, unlike attract. Total flux Φ is in webers; flux per square metre, B, is in teslas.", "formula": "Φ = B × A   (1 Wb = 1 T × 1 m²)", "example": "A uniform 0.2 T field passes straight through a 5 cm × 20 cm loop (A = 0.01 m²): Φ = 0.2 × 0.01 = 0.002 Wb = 2 mWb. Tilt the loop edge-on to the field and Φ drops to 0.", "refs": [{"book": "hughes", "ch": 6, "page": 133}, {"book": "gibilisco", "ch": 8, "page": 139}]},
  {"unit": 1, "title": "Current makes a magnetic field", "body": "Any current produces a magnetic field circling the wire, which is the basis of every electromagnet. Wind the wire into a coil (solenoid) and the fields add up, so it acts like a bar magnet; a steel core makes it much stronger. Reverse the current and the poles swap.", "formula": "Grip rule: thumb = current, fingers = field;  B = μ₀I ÷ (2πr)", "example": "A long wire carrying 10 A, at 1 cm away: B = 4π×10⁻⁷ × 10 ÷ (2π × 0.01) = 2×10⁻⁴ T = 0.2 mT, about four times Earth's field (≈ 50 μT).", "refs": [{"book": "hughes", "ch": 6, "page": 134}, {"book": "hughes", "ch": 7, "page": 149}]},
  {"unit": 1, "title": "Force on a current: motor effect", "body": "A current-carrying wire in a magnetic field feels a sideways push, at right angles to both the field and the current. This is how motors, loudspeakers and moving-coil meters work. Flip either the current or the field and the force reverses; flip both and it stays the same.", "formula": "F = B × I × l   (left hand: First=Field, seCond=Current, thuMb=Motion)", "example": "A 10 cm length of wire carrying 5 A at right angles to a 0.8 T field: F = 0.8 × 5 × 0.1 = 0.4 N. Double the current to 10 A and the force doubles to 0.8 N.", "refs": [{"book": "hughes", "ch": 6, "page": 136}, {"book": "hughes", "ch": 6, "page": 138}]},
  {"unit": 1, "title": "Electromagnetic induction: Faraday, Lenz", "body": "Change the flux through a coil, by moving a magnet or switching a nearby current, and a voltage is induced. Faraday: the faster the change and the more turns, the bigger the EMF. Lenz: the induced current always flows so as to oppose the change that caused it.", "formula": "e = N × ΔΦ ÷ Δt   (moving wire: e = B l u)", "example": "A 200-turn coil sees its flux rise from 0 to 3 mWb in 20 ms: e = 200 × 0.003 ÷ 0.02 = 30 V. Do it in 10 ms and e = 60 V. Steady flux, however large, gives 0 V.", "refs": [{"book": "hughes", "ch": 6, "page": 140}, {"book": "hughes", "ch": 6, "page": 143}]},
  {"unit": 1, "title": "Magnetic circuits: MMF, flux, reluctance", "body": "A magnetic circuit is the closed path flux takes, such as an iron ring. A coil's ampere-turns (MMF) drive flux round it, like EMF drives current; the path's reluctance opposes it, like resistance. Long, thin, or low-permeability paths have high reluctance; an air gap adds a lot.", "formula": "F = N I = Φ × S;   S = l ÷ (μ₀ μr A)", "example": "Steel ring: l = 0.3 m, A = 4 cm², μr = 1000. S = 0.3 ÷ (4π×10⁻⁷ × 1000 × 0.0004) ≈ 5.97×10⁵ A/Wb. 300 turns × 0.5 A = 150 A, so Φ = 150 ÷ 5.97×10⁵ ≈ 0.25 mWb.", "refs": [{"book": "hughes", "ch": 7, "page": 148}, {"book": "hughes", "ch": 7, "page": 153}]},
  {"unit": 1, "title": "Inductance and the inductor", "body": "An inductor is a coil that resists changes in its own current: any change alters its flux, which induces an EMF opposing the change (self-induction). Inductance L, in henrys, says how big that EMF is. It rises with the square of the turns, bigger core area and an iron core.", "formula": "e = L × ΔI ÷ Δt;   L = NΦ ÷ I;   L ∝ N²", "example": "A 0.2 H coil whose current rises from 0 to 0.5 A in 10 ms: e = 0.2 × 0.5 ÷ 0.01 = 10 V opposing the rise. Rewind it with twice the turns on the same core and L becomes 0.8 H.", "refs": [{"book": "hughes", "ch": 8, "page": 164}, {"book": "bishop", "ch": 7, "page": 55}]},
  {"unit": 1, "title": "RL circuits: the L/R time constant", "body": "Switch a DC supply onto a coil in series with R and the current cannot jump; it climbs along the same curve shape as a charging capacitor. The time constant is L/R: 63% of the final V/R after one, nearly full after five. Break it suddenly and the coil fights back with a spike.", "formula": "τ = L ÷ R;   i = (V/R)(1 − e^(−t/τ))", "example": "L = 0.5 H, R = 10 Ω, V = 12 V: τ = 0.5 ÷ 10 = 50 ms, final I = 12 ÷ 10 = 1.2 A. After 50 ms i ≈ 0.632 × 1.2 = 0.76 A; after 250 ms ≈ 1.19 A.", "refs": [{"book": "hughes", "ch": 8, "page": 172}, {"book": "hughes", "ch": 8, "page": 175}]},
  {"unit": 1, "title": "Energy stored in an inductor", "body": "While current builds up, energy goes into the inductor's magnetic field; when current falls, that energy comes back out. If the current is cut abruptly, the energy must go somewhere, often as a sparking arc or a voltage spike, which is why relay coils get a flyback diode.", "formula": "W = ½ L I²   joules", "example": "A 0.5 H coil carrying 1.2 A stores W = 0.5 × 0.5 × 1.2² = 0.36 J. At 2.4 A it would hold 1.44 J, four times as much.", "refs": [{"book": "hughes", "ch": 8, "page": 182}]},
  {"unit": 1, "title": "Mutual inductance, transformer principle", "body": "When two coils share flux, a changing current in one (primary) induces an EMF in the other (secondary). This is mutual inductance M, in henrys. It is the transformer's working principle: AC keeps the flux changing, so energy flows across with no wire link. Steady DC induces nothing.", "formula": "e₂ = M × ΔI₁ ÷ Δt;   M = N₂Φ₂ ÷ I₁", "example": "Two coils with M = 50 mH. The primary current changes by 2 A in 1 ms: e₂ = 0.05 × 2 ÷ 0.001 = 100 V in the secondary. Hold the primary at a steady 2 A and e₂ = 0 V.", "refs": [{"book": "hughes", "ch": 8, "page": 185}, {"book": "hughes", "ch": 34, "page": 682}]},
  {"unit": 1, "title": "Transformer turns ratio", "body": "Both windings see the same changing flux, so each turn gets the same volts. The voltage ratio therefore equals the turns ratio. Since an ideal transformer wastes almost no power, what it gains in voltage it loses in current: the current ratio is the turns ratio flipped.", "formula": "V₂/V₁ = N₂/N₁;   I₂/I₁ = N₁/N₂", "example": "230 V primary, 1000 turns; secondary 50 turns (20:1 step-down): V₂ = 230 × 50 ÷ 1000 = 11.5 V. A 2 A load draws I₁ = 2 × 50 ÷ 1000 = 0.1 A. Check: 11.5 × 2 = 230 × 0.1 = 23 W.", "refs": [{"book": "hughes", "ch": 34, "page": 682}, {"book": "gibilisco", "ch": 18, "page": 328}]},
  {"unit": 1, "title": "Impedance matching with a transformer", "body": "A transformer also scales impedance, by the square of its turns ratio. So a load can be made to look larger or smaller to the source. Matching the load to the source this way gives maximum power transfer, as in audio output stages and RF circuits.", "formula": "Z_pri ÷ Z_sec = (N_pri ÷ N_sec)²", "example": "An amplifier wants an 800 Ω load but the speaker is 8 Ω. Ratio needed = 800 ÷ 8 = 100, so turns ratio = √100 = 10:1. The 8 Ω speaker then looks like 8 × 10² = 800 Ω to the amplifier.", "refs": [{"book": "gibilisco", "ch": 18, "page": 338}]},
  {"unit": 2, "title": "What AC is: the sine wave", "body": "Alternating current keeps reversing direction: it rises to a maximum one way, falls through zero, then does the same the other way. A coil spinning in a magnetic field naturally makes this smooth sine shape, which is why mains power is a sine wave.", "formula": "v = Vm sin θ  (θ = angle turned since the zero crossing)", "example": "Vm = 325 V. At θ = 30°: v = 325 × 0.5 = 162.5 V. At 90°: v = 325 V (peak). At 210°: v = 325 × (−0.5) = −162.5 V, same size but reversed.", "refs": [{"book": "hughes", "ch": 9, "page": 198}, {"book": "gibilisco", "ch": 9, "page": 167}]},
  {"unit": 2, "title": "Frequency and period", "body": "One full repeat of the wave is a cycle. The time one cycle takes is the period T, and the number of cycles per second is the frequency f, measured in hertz (Hz). They are simply reciprocals: a short period means a high frequency.", "formula": "f = 1 ÷ T    T = 1 ÷ f", "example": "A wave repeats every 20 ms: f = 1 ÷ 0.020 = 50 Hz. A 2.5 MHz clock: T = 1 ÷ 2 500 000 = 0.4 μs per cycle.", "refs": [{"book": "hughes", "ch": 9, "page": 203}, {"book": "gibilisco", "ch": 9, "page": 165}]},
  {"unit": 2, "title": "Peak, peak-to-peak and RMS", "body": "Peak is the highest value from zero; peak-to-peak is the full swing from top to bottom. RMS (root-mean-square) is the 'effective' value: the DC level that would heat a resistor equally. Meters and mains ratings quote RMS.", "formula": "Vrms = Vm ÷ √2 ≈ 0.707 Vm    Vpp = 2Vm (sine wave)", "example": "Mains is 230 V RMS. Peak = 230 × 1.414 ≈ 325 V. Peak-to-peak = 2 × 325 ≈ 650 V. So a scope on mains shows a 650 V swing.", "refs": [{"book": "hughes", "ch": 9, "page": 205}, {"book": "gibilisco", "ch": 9, "page": 174}]},
  {"unit": 2, "title": "Average value and form factor", "body": "Over a full cycle a sine wave averages zero, so we average over one half-cycle instead. That half-cycle average is less than the RMS value. The ratio RMS ÷ average is the form factor; peak ÷ RMS is the crest (peak) factor. They describe the wave's shape.", "formula": "Iav = 0.637 Im   form factor = Irms÷Iav = 1.11   crest = 1.414", "example": "Sine with Im = 10 A: Iav = 6.37 A, Irms = 7.07 A. Form factor = 7.07 ÷ 6.37 = 1.11. Crest factor = 10 ÷ 7.07 = 1.414.", "refs": [{"book": "hughes", "ch": 9, "page": 206}, {"book": "hughes", "ch": 9, "page": 208}]},
  {"unit": 2, "title": "Phase and phase difference", "body": "Two waves of the same frequency can be shifted in time. That shift, measured as an angle (one cycle = 360°), is the phase difference. The wave that reaches its peak first leads; the other lags. Phase only makes sense when the frequencies are equal.", "formula": "phase difference = (time shift ÷ period) × 360°", "example": "Two 50 Hz waves (T = 20 ms); B peaks 5 ms after A. Shift = 5 ÷ 20 × 360° = 90°, so B lags A by 90°. If they were 180° apart with equal size, they would cancel.", "refs": [{"book": "gibilisco", "ch": 12, "page": 221}, {"book": "hughes", "ch": 9, "page": 214}]},
  {"unit": 2, "title": "Phasors: drawing AC as arrows", "body": "A phasor is an arrow whose length is the wave's size and whose angle is its phase. Picture it spinning anticlockwise at ω rad/s; its vertical shadow traces the sine wave. Same-frequency waves add like vectors, not like plain numbers.", "formula": "ω = 2πf    i = Im sin ωt", "example": "30 V at 0° plus 40 V at 90° (same frequency): resultant = √(30² + 40²) = 50 V at tan⁻¹(40÷30) = 53.1°. Not 70 V!", "refs": [{"book": "hughes", "ch": 9, "page": 212}, {"book": "hughes", "ch": 9, "page": 214}]},
  {"unit": 2, "title": "Resistor on AC: V and I in phase", "body": "In a pure resistor, current is simply voltage divided by R at every instant. So current and voltage rise, peak and cross zero together: they are in phase. Ohm's law works unchanged with RMS values.", "formula": "I = V ÷ R  (RMS values; phase angle 0°)", "example": "230 V RMS across a 46 Ω heater: I = 230 ÷ 46 = 5 A RMS. Peak current = 5 × 1.414 ≈ 7.07 A, occurring at the same instant as the 325 V voltage peak.", "refs": [{"book": "hughes", "ch": 10, "page": 223}]},
  {"unit": 2, "title": "Inductive reactance X_L", "body": "An inductor fights changes in current, so on AC it limits current even with almost no resistance. This opposition is inductive reactance, in ohms, and it grows with frequency. In a pure inductor the current lags the voltage by 90°.", "formula": "X_L = 2πfL   (current lags voltage by 90°)", "example": "100 mH at 50 Hz: X_L = 2π × 50 × 0.1 ≈ 31.4 Ω. On 230 V: I = 230 ÷ 31.4 ≈ 7.3 A. At 500 Hz, X_L = 314 Ω, so current drops tenfold.", "refs": [{"book": "hughes", "ch": 10, "page": 227}, {"book": "gibilisco", "ch": 13, "page": 233}]},
  {"unit": 2, "title": "Capacitive reactance X_C", "body": "A capacitor passes AC by charging and discharging each half-cycle. Its opposition, capacitive reactance, falls as frequency rises: it blocks DC but passes high frequencies easily. In a pure capacitor the current leads the voltage by 90°.", "formula": "X_C = 1 ÷ (2πfC)   (current leads voltage by 90°)", "example": "10 μF at 50 Hz: X_C = 1 ÷ (2π × 50 × 10×10⁻⁶) ≈ 318 Ω. On 230 V: I ≈ 0.72 A. At 1 kHz, X_C ≈ 15.9 Ω.", "refs": [{"book": "hughes", "ch": 10, "page": 233}, {"book": "gibilisco", "ch": 14, "page": 249}]},
  {"unit": 2, "title": "Impedance of series RL and RC", "body": "With R and a reactance in series, their voltages are 90° apart, so they add as a right-angled triangle. The total opposition is impedance Z, in ohms. In RL the current lags the supply; in RC it leads. The angle depends on X compared with R.", "formula": "Z = √(R² + X²)    φ = tan⁻¹(X ÷ R)    I = V ÷ Z", "example": "R = 30 Ω in series with X_L = 40 Ω: Z = √(900 + 1600) = 50 Ω. On 100 V: I = 2 A, lagging by tan⁻¹(40÷30) = 53.1°.", "refs": [{"book": "hughes", "ch": 10, "page": 229}, {"book": "gibilisco", "ch": 15, "page": 270}]},
  {"unit": 2, "title": "Series RLC circuits", "body": "In series RLC the inductor and capacitor voltages point in opposite directions, so their reactances subtract. Whichever is bigger decides if the circuit acts inductive (I lags) or capacitive (I leads). Each part's voltage can exceed the supply.", "formula": "Z = √(R² + (X_L − X_C)²)    φ = tan⁻¹((X_L − X_C) ÷ R)", "example": "R = 40 Ω, X_L = 100 Ω, X_C = 70 Ω: Z = √(40² + 30²) = 50 Ω. At 100 V, I = 2 A (lag 36.9°). V_L = 200 V and V_C = 140 V, both above the 100 V supply.", "refs": [{"book": "hughes", "ch": 10, "page": 236}, {"book": "gibilisco", "ch": 16, "page": 288}]},
  {"unit": 2, "title": "Parallel AC networks and admittance", "body": "In parallel, every branch sees the same voltage, so it is the reference. Branch currents add as phasors. It is easier to add admittances, Y = 1/Z, in siemens. Y splits into conductance G (in-phase part) and susceptance B (90° part).", "formula": "Y = 1 ÷ Z = G + jB    Y_total = Y₁ + Y₂ + …", "example": "50 Ω resistor parallel with X_C = 50 Ω on 100 V: I_R = 2 A, I_C = 2 A (leading). I = √(2² + 2²) ≈ 2.83 A, leading 45°. Z = 100 ÷ 2.83 ≈ 35.4 Ω.", "refs": [{"book": "hughes", "ch": 11, "page": 244}, {"book": "gibilisco", "ch": 15, "page": 276}]},
  {"unit": 2, "title": "Complex notation: the j operator", "body": "Multiplying by j means 'rotate 90° anticlockwise', and j² = −1. With it, an impedance becomes one number: real part R, imaginary part X. Rectangular form suits adding; polar form (size∠angle) suits multiplying and dividing.", "formula": "Z = R + jX_L  or  R − jX_C;   a + jb = √(a²+b²) ∠ tan⁻¹(b÷a)", "example": "Z = 3 + j4 Ω = 5∠53.1° Ω. With I = 2∠0° A: V = IZ = (2 × 5)∠(0° + 53.1°) = 10∠53.1° V. Multiply sizes, add angles.", "refs": [{"book": "hughes", "ch": 13, "page": 274}, {"book": "hughes", "ch": 13, "page": 276}]},
  {"unit": 2, "title": "Real, reactive and apparent power", "body": "Only resistance turns energy into heat or work: that is active (real) power, in watts. Reactive parts store energy and hand it back each cycle: reactive power, in var. V×I together is apparent power, in VA. They form a right triangle.", "formula": "P = VI cos φ   Q = VI sin φ   S = VI   S² = P² + Q²", "example": "230 V, 10 A, φ = 36.9° (cos φ = 0.8): S = 2300 VA, P = 2300 × 0.8 = 1840 W, Q = 2300 × 0.6 = 1380 var. Check: 1840² + 1380² = 2300².", "refs": [{"book": "hughes", "ch": 12, "page": 265}, {"book": "gibilisco", "ch": 17, "page": 309}]},
  {"unit": 2, "title": "Power factor and correcting it", "body": "Power factor is the share of apparent power that does real work. A low power factor means extra current for the same watts, so bigger cables and generators. Motors lag, so a capacitor in parallel supplies opposite var and cancels the lag.", "formula": "pf = cos φ = P ÷ S;  correction capacitor Q_C = load Q (for pf = 1)", "example": "4 kW load at pf 0.8 lag: S = 5 kVA, Q = 3 kvar, I = 5000÷230 ≈ 21.7 A. Add 3 kvar capacitor (≈181 μF at 230 V, 50 Hz): pf = 1, I = 4000÷230 ≈ 17.4 A.", "refs": [{"book": "hughes", "ch": 12, "page": 266}, {"book": "hughes", "ch": 13, "page": 291}]},
  {"unit": 2, "title": "Series resonance", "body": "At one frequency X_L equals X_C and they cancel. A series RLC then looks like just R: impedance is at its minimum, current at its maximum, and current is in phase with the supply. Below it the circuit is capacitive; above it, inductive.", "formula": "f_r = 1 ÷ (2π√(LC))    at f_r: Z = R, I = V ÷ R", "example": "L = 10 mH, C = 100 nF: √(LC) = √(10⁻⁹) ≈ 3.16×10⁻⁵ s, so f_r = 1 ÷ (2π × 3.16×10⁻⁵) ≈ 5.03 kHz. With R = 10 Ω and 1 V: I = 100 mA.", "refs": [{"book": "hughes", "ch": 14, "page": 302}, {"book": "gibilisco", "ch": 17, "page": 318}]},
  {"unit": 2, "title": "Parallel resonance", "body": "With L and C in parallel, at resonance their branch currents are equal and opposite, so they cancel at the supply. The circuit then has maximum impedance and draws minimum supply current, while a much larger current circulates between L and C.", "formula": "f_r = 1 ÷ (2π√(LC))  (ideal);  at f_r: Y = G, I = V ÷ R", "example": "L = 10 mH, C = 100 nF, R = 10 kΩ in parallel, 10 V at 5.03 kHz: supply I = 10 ÷ 10k = 1 mA. X_L ≈ 316 Ω, so I_L ≈ 31.6 mA circulates: 31.6× magnified.", "refs": [{"book": "hughes", "ch": 14, "page": 312}, {"book": "gibilisco", "ch": 17, "page": 319}]},
  {"unit": 2, "title": "Q factor and bandwidth", "body": "Q (quality factor) says how sharp a resonance is. In series RLC at resonance, the L and C voltages are Q times the supply. Bandwidth is the gap between the two half-power points (current down to 0.707 of max). High Q means a narrow, selective peak.", "formula": "Q = ω_r L ÷ R = (1÷R)√(L÷C)    BW = f_r ÷ Q", "example": "L = 10 mH, C = 100 nF, R = 10 Ω: Q = (1÷10) × √(10⁵) ≈ 31.6. f_r ≈ 5033 Hz, so BW = 5033 ÷ 31.6 ≈ 159 Hz. A 1 V supply puts ≈31.6 V across C.", "refs": [{"book": "hughes", "ch": 14, "page": 303}, {"book": "hughes", "ch": 14, "page": 307}]},
  {"unit": 2, "title": "Passive filters: low-pass, high-pass", "body": "An RC divider becomes a filter because X_C changes with frequency. Take output across C: low frequencies pass (low-pass). Take it across R: high frequencies pass (high-pass). At the cut-off frequency the output is 0.707 of the input (−3 dB, half power).", "formula": "f_c = 1 ÷ (2πRC);  at f_c: Vout = 0.707 Vin, phase shift 45°", "example": "R = 1 kΩ, C = 100 nF: f_c = 1 ÷ (2π × 1000 × 100×10⁻⁹) ≈ 1592 Hz. With 1 V in, output at 1.59 kHz is about 0.71 V for both low-pass and high-pass.", "refs": [{"book": "hughes", "ch": 17, "page": 368}, {"book": "bishop", "ch": 5, "page": 44}]},
  {"unit": 2, "title": "Three-phase supplies: star and delta", "body": "Three-phase uses three windings whose voltages are 120° apart. Star joins one end of each to a neutral; delta joins them in a closed loop. Balanced phases sum to zero, so fewer wires carry more power, and motors self-start.", "formula": "Star: V_L = √3 V_P, I_L = I_P;  Delta: V_L = V_P, I_L = √3 I_P", "example": "400 V star supply: phase voltage = 400 ÷ 1.732 ≈ 231 V. Balanced load at 10 A line, pf 0.8: P = √3 × 400 × 10 × 0.8 ≈ 5.54 kW.", "refs": [{"book": "hughes", "ch": 33, "page": 660}, {"book": "hughes", "ch": 33, "page": 665}]},
  {"unit": 3, "title": "Silicon's crystal structure", "body": "A silicon atom has four outer (valence) electrons. In a crystal each atom shares one with each of four neighbours, forming covalent bonds that lock the atoms in a neat lattice. Pure silicon is an insulator at absolute zero; at room temperature heat breaks a few bonds, so it conducts slightly.", "formula": "Si: 14 protons, 4 valence electrons → 4 covalent bonds per atom", "example": "1 cm³ of silicon holds ≈ 5×10²² atoms, but at room temperature only ≈ 10¹⁰ free electrons per cm³: about 1 free electron per 5×10¹² atoms. That is why pure silicon is a poor conductor.", "refs": [{"book": "hughes", "ch": 19, "page": 409}, {"book": "gibilisco", "ch": 19, "page": 360}]},
  {"unit": 3, "title": "Doping: N-type and P-type", "body": "Adding a tiny trace of impurity (doping) boosts conduction hugely. A 5-electron atom like phosphorus leaves one spare electron: N-type, carriers are electrons. A 3-electron atom like boron leaves a gap, a hole, which acts as a moving positive charge: P-type. The dopants are called donors and acceptors.", "formula": "Pentavalent (P, As, Sb) → N-type; trivalent (B, Ga, In) → P-type", "example": "Dope at 1 part in 10⁸: 5×10²² ÷ 10⁸ = 5×10¹⁴ donor atoms per cm³, each giving a free electron. That is 50 000 times the ≈10¹⁰ electrons in pure silicon.", "refs": [{"book": "hughes", "ch": 19, "page": 411}, {"book": "gibilisco", "ch": 19, "page": 362}]},
  {"unit": 3, "title": "The PN junction and depletion layer", "body": "Where P and N regions meet, electrons drift across into the P side and holes into the N side, cancelling each other. This leaves a thin zone with no free carriers, only fixed charged atoms: the depletion layer. Its charges set up a potential barrier that stops any more carriers crossing.", "formula": "Barrier potential ≈ 0.6–0.7 V (silicon), ≈ 0.2–0.3 V (germanium)", "example": "A 0.7 V barrier across a depletion layer 1 μm thick gives an electric field of 0.7 ÷ (1×10⁻⁶) = 700 000 V/m, strong enough to sweep stray carriers back to their own side.", "refs": [{"book": "hughes", "ch": 19, "page": 413}, {"book": "bishop", "ch": 1, "page": 8}]},
  {"unit": 3, "title": "The diode: forward and reverse bias", "body": "A diode is a single PN junction. Make the anode (P side) positive and the barrier is pushed down, so current flows easily: forward bias. Reverse the supply and the depletion layer widens, so only a tiny leakage current flows: reverse bias. It is a one-way valve for current.", "formula": "Anode + relative to cathode → conducts; cathode + → blocks", "example": "5 V supply, diode and 1 kΩ in series. Forward: I ≈ (5 − 0.7) ÷ 1000 = 4.3 mA. Diode reversed: only leakage, say 10 nA, so the resistor drops just 10 nA × 1 kΩ = 10 μV.", "refs": [{"book": "hughes", "ch": 19, "page": 414}, {"book": "gibilisco", "ch": 19, "page": 364}]},
  {"unit": 3, "title": "Diode curve and the 0.7 V drop", "body": "A diode does not obey Ohm's law: its I–V graph is a curve. Almost no current flows until about 0.6 V, then current shoots up steeply, so a conducting silicon diode drops roughly 0.7 V whatever the current. Reverse leakage is tiny but roughly doubles for each 8–10 °C rise.", "formula": "I = Is(e^(38.6V) − 1) at 27 °C;  rule of thumb: V_F ≈ 0.7 V (Si)", "example": "Take Is = 10⁻¹⁴ A. At 0.6 V: I ≈ 10⁻¹⁴ × e^23.2 ≈ 0.11 mA. At 0.7 V: I ≈ 10⁻¹⁴ × e^27.0 ≈ 5.4 mA. Only 0.1 V more gives about 47 times the current.", "refs": [{"book": "hughes", "ch": 19, "page": 416}, {"book": "bishop", "ch": 1, "page": 5}]},
  {"unit": 3, "title": "Half-wave rectifier", "body": "Rectifying means turning AC into one-way current. A single diode in series with the load passes only the positive half-cycles and blocks the negative ones. The output is bumpy pulsed DC with gaps, and half of each cycle is wasted, so it suits only small, cheap supplies.", "formula": "V_dc = Vm ÷ π ≈ 0.318 Vm  (Vm = peak across load)", "example": "12 V rms transformer: Vm = 12 × √2 = 16.97 V. Minus 0.7 V diode drop: 16.27 V peak. Average DC = 16.27 ÷ π ≈ 5.18 V. Diode must block about 17 V in reverse.", "refs": [{"book": "hughes", "ch": 20, "page": 420}, {"book": "gibilisco", "ch": 21, "page": 386}]},
  {"unit": 3, "title": "Full-wave and bridge rectifiers", "body": "Full-wave rectifiers use both halves of the AC cycle, flipping the negative half upright. A centre-tapped transformer with two diodes does it, or a bridge of four diodes with a plain winding. Average output doubles and ripple is at twice mains frequency, making it easier to smooth.", "formula": "V_dc = 2Vm ÷ π ≈ 0.637 Vm;  ripple frequency = 2 × f_supply", "example": "Bridge on 12 V rms: Vm = 16.97 V. Two diodes conduct at once: 16.97 − 1.4 = 15.57 V peak. Average DC = 0.637 × 15.57 ≈ 9.91 V, with ripple at 2 × 50 = 100 Hz.", "refs": [{"book": "hughes", "ch": 20, "page": 423}, {"book": "gibilisco", "ch": 21, "page": 387}]},
  {"unit": 3, "title": "Smoothing capacitor and ripple", "body": "A big capacitor across the rectifier output charges to the peak on each pulse, then feeds the load while the input dips. The output sags a little between peaks, giving a sawtooth ripple. More load current means more ripple; a bigger capacitor or higher ripple frequency means less.", "formula": "Ripple (pk-pk) ≈ I ÷ (f × C),  f = ripple frequency", "example": "Full-wave on 50 Hz mains (f = 100 Hz), load 0.5 A, C = 2200 μF: ripple ≈ 0.5 ÷ (100 × 0.0022) ≈ 2.27 V. Using 4700 μF instead: 0.5 ÷ 0.47 ≈ 1.06 V.", "refs": [{"book": "hughes", "ch": 20, "page": 427}, {"book": "bishop", "ch": 17, "page": 144}]},
  {"unit": 3, "title": "Zener diode voltage regulator", "body": "A Zener diode is built to break down safely at a set reverse voltage, Vz. Once in breakdown its voltage stays almost constant over a wide current range. With a series resistor it holds a load at Vz even when the input varies; it needs a few mA of its own current to keep regulating.", "formula": "R = (Vin − Vz) ÷ (I_load(max) + I_z(min))", "example": "Vin = 12 V, Vz = 5.1 V, load up to 50 mA, Iz min 5 mA: R = 6.9 ÷ 0.055 ≈ 125 Ω, use 120 Ω. With no load all 57.5 mA flows in the Zener: P = 0.0575 × 5.1 ≈ 0.29 W.", "refs": [{"book": "hughes", "ch": 20, "page": 429}, {"book": "bishop", "ch": 17, "page": 145}]},
  {"unit": 3, "title": "LEDs and photodiodes", "body": "An LED gives out light when forward biased; the colour depends on its semiconductor mix and it drops about 2 V, not 0.7 V. It always needs a series resistor to limit current. A photodiode works the other way: reverse biased, it passes a small leakage current that grows with the brightness of the light reaching it.", "formula": "LED resistor: R = (Vs − V_F) ÷ I_F", "example": "Red LED (V_F = 2.0 V) at 15 mA from 5 V: R = (5 − 2.0) ÷ 0.015 = 200 Ω. Nearest standard 220 Ω gives I = 3.0 ÷ 220 ≈ 13.6 mA, a little dimmer but safe.", "refs": [{"book": "gibilisco", "ch": 20, "page": 378}, {"book": "bishop", "ch": 1, "page": 6}]},
  {"unit": 3, "title": "The bipolar junction transistor", "body": "A BJT is a thin base layer sandwiched between emitter and collector: NPN or PNP. With the base-emitter junction forward biased and the base-collector junction reverse biased, nearly all carriers from the emitter rush through the thin base to the collector. A small base current controls a large collector current.", "formula": "IE = IB + IC", "example": "An NPN transistor has IE = 2 mA and 99% of it reaches the collector: IC = 0.99 × 2 = 1.98 mA, so IB = 2 − 1.98 = 0.02 mA = 20 μA.", "refs": [{"book": "hughes", "ch": 21, "page": 434}, {"book": "gibilisco", "ch": 22, "page": 400}]},
  {"unit": 3, "title": "Current gain (beta / hFE)", "body": "Beta (β, or hFE on datasheets) tells how many times bigger the collector current is than the base current, typically 50 to 500. Alpha (α) compares collector to emitter current and is just under 1. Beta varies a lot between transistors of the same type, so good circuits must not depend on its exact value.", "formula": "hFE = IC ÷ IB    α = β ÷ (1 + β)", "example": "IB = 20 μA gives IC = 3 mA: hFE = 3 mA ÷ 20 μA = 150. Then α = 150 ÷ 151 ≈ 0.993, so 99.3% of the emitter current reaches the collector.", "refs": [{"book": "hughes", "ch": 21, "page": 438}, {"book": "gibilisco", "ch": 22, "page": 405}]},
  {"unit": 3, "title": "The transistor as a switch", "body": "As a switch, a BJT is either cut off (no base current, no collector current) or saturated (enough base current that it is fully on, with only ~0.2 V across it). It lets a tiny control current switch a big load. Give extra base current so it saturates even with a low-gain transistor.", "formula": "Saturate: IB > IC ÷ hFE(min), use 2–10× margin;  V_CE(sat) ≈ 0.2 V", "example": "Relay coil 400 Ω on 12 V: IC ≈ 12 ÷ 400 = 30 mA. hFE(min) = 100 → IB ≥ 0.3 mA; choose 1 mA. From a 5 V logic pin: RB = (5 − 0.7) ÷ 0.001 = 4.3 kΩ.", "refs": [{"book": "bishop", "ch": 2, "page": 14}, {"book": "hughes", "ch": 21, "page": 458}]},
  {"unit": 3, "title": "Biasing a transistor amplifier", "body": "To amplify AC both ways, the transistor needs a steady 'quiescent' current so it sits mid-way between cut-off and saturation. A single base resistor works but depends on beta. A voltage divider on the base plus an emitter resistor fixes the current set almost by resistors alone.", "formula": "VB = VCC × R2 ÷ (R1 + R2);  IC ≈ (VB − 0.7) ÷ RE", "example": "VCC = 15 V, R1 = 120 kΩ, R2 = 15 kΩ: VB = 15 × 15 ÷ 135 ≈ 1.67 V. Emitter at 1.67 − 0.7 = 0.97 V; with RE = 1 kΩ, IC ≈ 0.97 mA, almost regardless of beta.", "refs": [{"book": "hughes", "ch": 21, "page": 441}, {"book": "bishop", "ch": 9, "page": 74}]},
  {"unit": 3, "title": "Common-emitter amplifier", "body": "In the common-emitter amplifier the signal goes into the base and comes out at the collector. A small change in base current makes a big change in collector current, which the collector resistor turns into a big voltage swing. The output is inverted: input up, output down.", "formula": "Av ≈ −RC ÷ RE  (emitter resistor not bypassed)", "example": "RC = 6.8 kΩ, RE = 680 Ω: Av ≈ −6800 ÷ 680 = −10. A 50 mV peak input gives a 0.5 V peak output, upside down. Bypassing RE with a capacitor raises the gain but makes it less stable.", "refs": [{"book": "bishop", "ch": 9, "page": 71}, {"book": "hughes", "ch": 21, "page": 441}]},
  {"unit": 3, "title": "Emitter follower (common collector)", "body": "Here the output is taken from the emitter. The emitter just follows the base, always about 0.7 V lower, so voltage gain is about 1 with no inversion. Its value is high input resistance and low output resistance, so it works as a buffer that lets a weak source drive a heavy load.", "formula": "Av ≈ 1;  R_in ≈ hFE × RE;  V_E = V_B − 0.7 V", "example": "RE = 1 kΩ, hFE = 200: input resistance ≈ 200 × 1 kΩ = 200 kΩ (before bias resistors). With 3.7 V on the base, the emitter sits at 3.0 V and passes 3.0 ÷ 1000 = 3 mA.", "refs": [{"book": "bishop", "ch": 9, "page": 75}, {"book": "gibilisco", "ch": 22, "page": 410}]},
  {"unit": 3, "title": "The junction FET (JFET)", "body": "A JFET is a channel of N-type silicon with a P-type gate. Reverse biasing the gate grows depletion layers that squeeze the channel, so a more negative gate voltage means less drain current, until pinch-off. It is voltage controlled and the gate draws almost no current, giving very high input resistance.", "formula": "gm = ΔID ÷ ΔVGS   (transconductance, in siemens)", "example": "VGS goes from −2.0 V to −1.8 V and ID rises from 2.0 mA to 2.5 mA: gm = 0.5 mA ÷ 0.2 V = 2.5 mS. With a 4.7 kΩ drain resistor, gain ≈ 2.5 mS × 4.7 kΩ ≈ 11.8.", "refs": [{"book": "hughes", "ch": 22, "page": 465}, {"book": "gibilisco", "ch": 23, "page": 416}]},
  {"unit": 3, "title": "The MOSFET", "body": "In a MOSFET the gate is a metal plate insulated from the channel by a thin layer of silicon dioxide, so practically no gate current flows. In the common N-channel enhancement type there is no channel at 0 V; when VGS passes the threshold voltage a channel forms and drain current grows rapidly.", "formula": "ID ≈ 0 for VGS < V_th;  above it gm = ΔID ÷ ΔVGS", "example": "V_th = 2 V, so at VGS = 1.5 V the MOSFET is off. Raising VGS from 3.0 V to 3.4 V lifts ID from 40 mA to 100 mA: gm = 60 mA ÷ 0.4 V = 150 mS.", "refs": [{"book": "hughes", "ch": 22, "page": 467}, {"book": "bishop", "ch": 8, "page": 63}]},
  {"unit": 3, "title": "The FET as a switch", "body": "A MOSFET makes a near-ideal switch. The insulated gate takes no steady current, so a logic output can drive it. Off, the drain-source path is almost open; fully on, it behaves like a small resistor, RDS(on). There is no 0.7 V or saturation drop as with a BJT, only I × RDS(on).", "formula": "Loss when on: P = I² × RDS(on);  drop = I × RDS(on)", "example": "Switching a 5 A load with RDS(on) = 0.05 Ω: drop = 5 × 0.05 = 0.25 V, heat = 5² × 0.05 = 1.25 W. A BJT (hFE 100) would also need about 50 mA of base drive.", "refs": [{"book": "hughes", "ch": 22, "page": 471}, {"book": "bishop", "ch": 2, "page": 11}]},
  {"unit": 3, "title": "Gain in decibels and bandwidth", "body": "Gains multiply through stages, so engineers use decibels, which simply add. An amplifier's gain is flat in mid-band but falls at low and high frequencies. The bandwidth is the range between the two −3 dB points, where gain has dropped to 0.707 of mid-band (half power).", "formula": "Av(dB) = 20 log₁₀(Vout ÷ Vin);  BW = f₂ − f₁ at −3 dB", "example": "20 mV in, 2 V out: ratio 100, gain = 20 × log 100 = 40 dB. If gain falls to 37 dB (×0.707) at 50 Hz and 25 kHz, bandwidth = 25 000 − 50 = 24 950 Hz.", "refs": [{"book": "gibilisco", "ch": 24, "page": 434}, {"book": "hughes", "ch": 18, "page": 396}]},
  {"unit": 3, "title": "Negative feedback", "body": "Negative feedback sends a fraction β of the output back to oppose the input. It lowers the gain, but in return the gain becomes set by the feedback network rather than the fickle transistor, and bandwidth widens and distortion falls. Almost every precision amplifier relies on it.", "formula": "Gain with feedback = A ÷ (1 + βA) ≈ 1 ÷ β  when βA ≫ 1", "example": "A = 100 000, β = 0.01: gain = 100 000 ÷ 1001 ≈ 99.9. If A halves to 50 000: gain = 50 000 ÷ 501 ≈ 99.8. Amplifier gain halved, yet overall gain barely moved.", "refs": [{"book": "hughes", "ch": 18, "page": 397}]},
  {"unit": 3, "title": "The operational amplifier", "body": "An op amp is an IC differential amplifier with two inputs, inverting (−) and non-inverting (+), and huge open-loop gain. Ideally: infinite gain and input resistance, zero output resistance. Real ones get close (gain ~10⁵, input MΩ or more) and are always used with feedback to set a precise gain.", "formula": "Vout = A × (V₊ − V₋),  A ≈ 10⁵ (open loop)", "example": "A = 100 000 on a supply that lets the output swing ±12 V: a difference of only 12 ÷ 100 000 = 120 μV between the inputs drives the output to its limit.", "refs": [{"book": "bishop", "ch": 11, "page": 87}, {"book": "hughes", "ch": 23, "page": 480}]},
  {"unit": 3, "title": "Inverting amplifier", "body": "The input feeds the − input through Rin, and Rf feeds the output back to it; + is grounded. Feedback holds − at 0 V too (a 'virtual earth'), so the same current flows through both resistors. Gain depends only on the resistor ratio, and the output is inverted. Input resistance equals Rin.", "formula": "Av = −Rf ÷ Rin", "example": "Rin = 4.7 kΩ, Rf = 47 kΩ: Av = −47 ÷ 4.7 = −10. An input of +0.25 V gives −2.5 V out. Input current = 0.25 ÷ 4700 ≈ 53 μA, which all flows on through Rf.", "refs": [{"book": "bishop", "ch": 11, "page": 90}, {"book": "hughes", "ch": 23, "page": 481}]},
  {"unit": 3, "title": "Non-inverting amp and voltage follower", "body": "Here the signal enters the + input and a divider feeds part of the output back to −. Feedback makes both inputs equal, giving in-phase gain set by two resistors and a very high input resistance. Feed all the output back (no divider) and the gain is exactly 1: a voltage follower, an ideal buffer.", "formula": "Av = 1 + Rf ÷ R1;  follower: Av = 1", "example": "R1 = 2.2 kΩ, Rf = 22 kΩ: Av = 1 + 10 = 11. An input of 0.3 V gives 3.3 V out, not inverted. As a follower, a sensor reading 1.8 V gives 1.8 V out, now able to drive a load.", "refs": [{"book": "bishop", "ch": 11, "page": 93}, {"book": "hughes", "ch": 23, "page": 484}]},
  {"unit": 3, "title": "Comparators and the Schmitt trigger", "body": "With no feedback an op amp is a comparator: the output slams high or low depending on which input is higher. A noisy input near the switch point makes it chatter. A Schmitt trigger adds positive feedback, giving two thresholds; the gap (hysteresis) ignores noise and snaps cleanly.", "formula": "Hysteresis = UTV − LTV;  thresholds = ±Vsat × R2 ÷ (R1 + R2)", "example": "Input on −, output swings ±10 V; feedback divider R1 = 90 kΩ (out to +), R2 = 10 kΩ (+ to 0 V): thresholds = ±10 × 10 ÷ 100 = ±1 V. Hysteresis = 1 − (−1) = 2 V of noise immunity.", "refs": [{"book": "bishop", "ch": 11, "page": 89}, {"book": "bishop", "ch": 12, "page": 101}]},
  {"unit": 3, "title": "Summing and difference amplifiers", "body": "A summing amplifier is an inverting amp with several input resistors meeting at the virtual earth; their currents add in Rf, so the output is the (inverted) weighted sum. A difference amplifier feeds one signal to each input and outputs their difference, rejecting noise common to both.", "formula": "Sum: Vout = −Rf(V1/R1 + V2/R2);  diff (equal R): Vout = V2 − V1", "example": "Summer, all 10 kΩ: V1 = 0.5 V, V2 = 1.2 V → Vout = −1.7 V. Difference amp, all 10 kΩ: V2 = 2.30 V on +, V1 = 2.25 V on − → Vout = 0.05 V; any shared hum cancels.", "refs": [{"book": "bishop", "ch": 12, "page": 97}, {"book": "hughes", "ch": 23, "page": 482}]},
  {"unit": 3, "title": "The integrator", "body": "Swap the feedback resistor of an inverting amp for a capacitor. The input current charges the capacitor, so the output is the running total (integral) of the input over time, inverted. A steady input gives a straight-line ramp, handy for timers, ramp generators and averaging.", "formula": "Vout = −(1 ÷ RC) ∫ Vin dt;  steady Vin: slope = −Vin ÷ RC", "example": "R = 100 kΩ, C = 1 μF, so RC = 0.1 s. A steady +0.5 V input makes the output fall at 0.5 ÷ 0.1 = 5 V/s. After 2 s it reaches −10 V, just inside a ±15 V supply.", "refs": [{"book": "bishop", "ch": 12, "page": 100}]},
  {"unit": 3, "title": "Active filters", "body": "An active filter combines an RC network with an op amp. The RC sets the cut-off frequency; the op amp buffers it and can add gain, so no bulky inductors are needed and the signal isn't weakened. A first-order stage rolls off at 20 dB per decade; stages can be cascaded for sharper cut-off.", "formula": "fc = 1 ÷ (2πRC);  passband gain = 1 + RF ÷ RA", "example": "Low-pass with R = 10 kΩ, C = 15 nF: fc = 1 ÷ (2π × 10⁴ × 15×10⁻⁹) ≈ 1061 Hz. With RF = RA = 10 kΩ, passband gain = 2 (6 dB). At about 10.6 kHz it is 20 dB below that.", "refs": [{"book": "bishop", "ch": 13, "page": 111}]},
  {"unit": 3, "title": "Oscillators: feedback makes a wave", "body": "An oscillator is an amplifier that feeds its own output back in phase (positive feedback). A frequency-selective network lets this happen at just one frequency, so tiny random noise at that frequency builds into a steady wave. It needs loop gain of at least 1 to keep going.", "formula": "Loop gain ≥ 1, feedback in phase;  Wien bridge: f = 1 ÷ (2πRC)", "example": "Wien bridge with R = 16 kΩ, C = 10 nF: f = 1 ÷ (2π × 16 000 × 10×10⁻⁹) ≈ 995 Hz. The Wien network passes 1/3 of the signal there, so the amp needs a gain of at least 3.", "refs": [{"book": "gibilisco", "ch": 25, "page": 458}, {"book": "bishop", "ch": 14, "page": 120}]},
  {"unit": 3, "title": "Power amplifiers: class A, B, AB", "body": "Power amps boost current to drive speakers or motors. Class A conducts all the time, so it is linear but wastes power even when silent. Class B uses a push-pull pair, each half handling half the wave: efficient, but distorts near zero (crossover). Class AB biases both slightly on to cure it.", "formula": "Class B maximum efficiency = π ÷ 4 ≈ 78.5%", "example": "Push-pull on ±15 V into an 8 Ω speaker, peak swing 14 V: peak current = 14 ÷ 8 = 1.75 A. Sine output power = 14² ÷ (2 × 8) ≈ 12.3 W.", "refs": [{"book": "bishop", "ch": 15, "page": 124}, {"book": "gibilisco", "ch": 24, "page": 439}]},
  {"unit": 3, "title": "Thyristors and triacs", "body": "A thyristor (SCR) is a four-layer PNPN switch. A short gate pulse turns it on, and it then latches on until its current falls to near zero, which on AC happens every half-cycle. Delaying the trigger controls how much power reaches the load. A triac conducts both ways and suits AC dimmers.", "formula": "Conduction angle = 180° − firing angle (per half-cycle)", "example": "50 Hz mains (period 20 ms), trigger 2.5 ms after each zero crossing: firing angle = 360° × 2.5 ÷ 20 = 45°, so the thyristor conducts for 180° − 45° = 135° of each half-cycle.", "refs": [{"book": "bishop", "ch": 16, "page": 131}, {"book": "hughes", "ch": 45, "page": 916}]},
  {"unit": 3, "title": "Linear regulated power supplies", "body": "A linear supply chains transformer, rectifier, smoothing capacitor and regulator. The regulator (a Zener with emitter follower, or an IC) holds the output fixed despite ripple and load changes, burning off the extra voltage as heat. The input must stay above output plus a dropout margin.", "formula": "Regulator heat: P = (Vin − Vout) × I_load", "example": "A 5 V regulator fed 9 V average and supplying 0.5 A dissipates (9 − 5) × 0.5 = 2 W, so it needs a heatsink. Ripple troughs must stay above about 7 V for a 2 V dropout.", "refs": [{"book": "bishop", "ch": 17, "page": 146}, {"book": "gibilisco", "ch": 21, "page": 392}]},
  {"unit": 4, "title": "Analogue vs digital signals", "body": "An analogue signal varies smoothly and can take any value in its range, like a microphone voltage. A digital signal uses only a few fixed levels, usually two (1 and 0). A slightly weakened 1 is still clearly a 1, so digital signals can be regenerated without losing information.", "formula": "n bits give 2ⁿ distinct levels; analogue has unlimited levels", "example": "A 5 V 'high' arrives as 4.1 V after a long cable. The receiver still reads it as 1 and re-sends a clean 5 V. An analogue 4.1 V would simply be a wrong value, 18% low.", "refs": [{"book": "hughes", "ch": 30, "page": 624}, {"book": "hughes", "ch": 26, "page": 524}]},
  {"unit": 4, "title": "Binary numbers", "body": "Binary is base 2: only the digits 0 and 1, called bits. Each position is worth twice the one to its right: 1, 2, 4, 8, 16 and so on. The rightmost bit is the LSB, the leftmost the MSB. To convert decimal to binary, divide by 2 repeatedly and read the remainders from the bottom up.", "formula": "Value = Σ bitₖ × 2ᵏ  (k = 0 for the LSB)", "example": "1101₂ = 8 + 4 + 0 + 1 = 13. Back again: 13÷2 = 6 r1, 6÷2 = 3 r0, 3÷2 = 1 r1, 1÷2 = 0 r1; reading the remainders upward gives 1101₂.", "refs": [{"book": "hughes", "ch": 25, "page": 509}, {"book": "gibilisco", "ch": 30, "page": 556}]},
  {"unit": 4, "title": "Hexadecimal and BCD", "body": "Hexadecimal is base 16, using 0–9 then A–F for 10–15. One hex digit stands for exactly 4 bits, so long binary words become short and readable. BCD (binary-coded decimal) instead codes each decimal digit separately in 4 bits (0000–1001), which suits displays and decimal readouts.", "formula": "1 hex digit = 4 bits;  one BCD digit = 0000 to 1001 (0–9)", "example": "1011 0110₂ = B6₁₆ = 11×16 + 6 = 182. In BCD, 182 is written 0001 1000 0010: one 4-bit group for each decimal digit 1, 8 and 2.", "refs": [{"book": "hughes", "ch": 25, "page": 521}, {"book": "hughes", "ch": 24, "page": 493}]},
  {"unit": 4, "title": "Binary addition, two's complement", "body": "Binary adds like decimal: 1+1 = 0 carry 1, and 1+1+1 = 1 carry 1. Negative numbers are usually stored in two's complement: invert every bit, then add 1. The MSB then acts as a sign bit (1 = negative), and subtraction becomes simply adding the negative number.", "formula": "−N = (invert all bits of N) + 1;  A − B = A + (−B), drop final carry", "example": "8-bit 12 − 5: 5 = 00000101 → invert 11111010 → +1 = 11111011. Then 00001100 + 11111011 = 1 00000111; drop the carry → 00000111 = 7.", "refs": [{"book": "hughes", "ch": 25, "page": 511}, {"book": "hughes", "ch": 25, "page": 515}]},
  {"unit": 4, "title": "Logic gates: AND, OR, NOT", "body": "Logic gates are switching circuits that work on 1s and 0s. AND gives 1 only when all inputs are 1 (like switches in series). OR gives 1 when any input is 1 (switches in parallel). NOT has one input and gives the opposite. Every digital system is built from these ideas.", "formula": "AND: F = A·B    OR: F = A + B    NOT: F = Ā", "example": "With A=1, B=0: AND gives 0, OR gives 1, and NOT A gives 0. A 4-input AND gives 1 for only one of its 2⁴ = 16 input patterns: 1111.", "refs": [{"book": "hughes", "ch": 26, "page": 524}, {"book": "bishop", "ch": 18, "page": 149}]},
  {"unit": 4, "title": "NAND, NOR and XOR", "body": "NAND is AND followed by NOT: its output is 0 only when all inputs are 1. NOR is OR followed by NOT: its output is 1 only when all inputs are 0. XOR (exclusive-OR) gives 1 when its two inputs differ, so it works as a 'same or different' detector.", "formula": "NAND = NOT(A·B);  NOR = NOT(A+B);  A⊕B = 1 only if A ≠ B", "example": "A=1, B=1: AND=1 so NAND=0; OR=1 so NOR=0; XOR=0 (same). A=1, B=0: NAND=1, NOR=0, XOR=1 (different).", "refs": [{"book": "bishop", "ch": 18, "page": 151}, {"book": "hughes", "ch": 26, "page": 527}]},
  {"unit": 4, "title": "Truth tables and Boolean algebra", "body": "A truth table lists every input combination (2ⁿ rows for n inputs) and the output for each. Boolean algebra writes the same logic as equations: · for AND, + for OR, a bar for NOT. Its rules let you simplify a circuit on paper before you build it, saving gates.", "formula": "A+0=A, A·1=A, A+Ā=1, A·Ā=0, A+A·B=A", "example": "3 inputs need 2³ = 8 rows. Simplify F = A·B + A·B̄: take out A → A·(B + B̄) = A·1 = A. Two AND gates and an OR gate collapse into a plain wire from A.", "refs": [{"book": "bishop", "ch": 19, "page": 157}, {"book": "hughes", "ch": 26, "page": 529}]},
  {"unit": 4, "title": "De Morgan; NAND as universal gate", "body": "De Morgan's theorem: breaking a bar over a group flips the operator, so NOT(A·B) = Ā + B̄ and NOT(A+B) = Ā·B̄. Because of this, NAND gates alone (or NOR alone) can make NOT, AND and OR, so any logic can be built from one gate type, which simplifies stock and board layout.", "formula": "NOT(A·B) = Ā + B̄;   NOT(A+B) = Ā·B̄", "example": "NOT: tie a NAND's inputs together, NOT(A·A) = Ā. AND: a NAND then a NAND inverter (2 gates). OR: invert A and B with NANDs, then NAND them: NOT(Ā·B̄) = A+B (3 gates).", "refs": [{"book": "hughes", "ch": 26, "page": 530}, {"book": "bishop", "ch": 19, "page": 162}]},
  {"unit": 4, "title": "Karnaugh maps", "body": "A Karnaugh map redraws a truth table as a grid where neighbouring cells differ by one bit (order 00, 01, 11, 10). Circle groups of 1s of size 1, 2, 4 or 8, as large as possible; edges wrap round. Each group drops the variables that change inside it, giving the simplest sum of products.", "formula": "A group of 2ᵏ adjacent 1s removes k variables from its term", "example": "F = 1 for ABC = 001, 011, 101, 111. These four cells form one group in which A and B change but C = 1 throughout, so F = C: one wire instead of four 3-input ANDs.", "refs": [{"book": "hughes", "ch": 26, "page": 535}, {"book": "bishop", "ch": 19, "page": 160}]},
  {"unit": 4, "title": "Logic families: TTL and CMOS", "body": "TTL is built from bipolar transistors and needs a tight 5 V supply. CMOS uses complementary n- and p-channel MOSFET pairs, draws almost no current when idle and works over a wide supply range, but is sensitive to static. Each family defines voltage bands for a valid 1 and 0; the gap between them is the noise margin.", "formula": "Noise margin (high) = VOH(min) − VIH(min)", "example": "A 74LS output gives at least 2.7 V for a 1; an input accepts ≥ 2.0 V as 1, so the high noise margin = 0.7 V. Low: output ≤ 0.5 V vs input limit 0.8 V → 0.3 V.", "refs": [{"book": "bishop", "ch": 18, "page": 152}, {"book": "hughes", "ch": 26, "page": 552}]},
  {"unit": 4, "title": "Combinational circuits: adders", "body": "A half adder adds two bits: the sum is A XOR B and the carry is A AND B. A full adder also accepts a carry-in from the previous column, so full adders can be chained to add multi-bit numbers, each carry-out feeding the next stage's carry-in.", "formula": "S = A⊕B⊕Cᵢ;   Cₒ = A·B + A·Cᵢ + B·Cᵢ", "example": "Full adder with A=1, B=1, Ci=1: S = 1⊕1⊕1 = 1 and Co = 1 (most inputs are 1), i.e. 1+1+1 = 11₂ = 3. A half adder with A=1, B=1 gives S = 0, C = 1.", "refs": [{"book": "bishop", "ch": 20, "page": 168}]},
  {"unit": 4, "title": "Multiplexers and decoders", "body": "A multiplexer (data selector) has several data inputs and one output; binary address lines choose which input reaches the output. A decoder works the other way: it takes a binary code and drives exactly one of its outputs high. A demultiplexer routes one data line to the selected output.", "formula": "n address lines select 1 of 2ⁿ inputs (mux) or outputs (decoder)", "example": "An 8-input mux needs log₂8 = 3 address lines; address 101 (= 5) passes input D5 to the output. A 2-to-4 decoder given 10 makes output 2 high and the other three low.", "refs": [{"book": "bishop", "ch": 20, "page": 171}, {"book": "bishop", "ch": 20, "page": 170}]},
  {"unit": 4, "title": "Latches and flip-flops", "body": "A latch (flip-flop) is a bistable: two gates feed each other so the circuit stays in either state, storing one bit. An SR latch is set (Q=1) or reset (Q=0) by its inputs and remembers the last command. Asking it to set and reset at once is the forbidden, unpredictable case.", "formula": "SR: S=1→Q=1; R=1→Q=0; both 0 → hold; both 1 → not allowed", "example": "Debounce: a push-button bounces 5 times in 2 ms. Wired through a changeover switch to an SR latch, the first contact sets Q=1 and later bounces just repeat 'set', so one clean edge results.", "refs": [{"book": "hughes", "ch": 26, "page": 544}, {"book": "bishop", "ch": 21, "page": 177}]},
  {"unit": 4, "title": "D and JK flip-flops; clocking", "body": "Clocked flip-flops change only at a clock edge, so a whole system updates in step. A D flip-flop copies D to Q at each active edge and holds it until the next. A JK flip-flop holds (J=K=0), resets (J=0, K=1), sets (J=1, K=0) or toggles (J=K=1), removing the SR's forbidden state.", "formula": "D: Qₙ₊₁ = D;   JK: Qₙ₊₁ = J·Q̄ₙ + K̄·Qₙ", "example": "A JK flip-flop with J = K = 1 clocked at 10 MHz toggles on every active edge, so Q is a 5 MHz square wave: it divides the clock by 2. A D-type does the same with Q̄ wired back to D.", "refs": [{"book": "bishop", "ch": 21, "page": 182}, {"book": "hughes", "ch": 26, "page": 548}]},
  {"unit": 4, "title": "Counters", "body": "Chaining toggling flip-flops makes a counter: each stage switches at half the rate of the one before, so the outputs step through the binary numbers. In a ripple counter each stage clocks the next, causing brief wrong counts (glitches); a synchronous counter clocks all stages together to avoid them.", "formula": "n flip-flops: count 0 to 2ⁿ − 1;  last output = f_clock ÷ 2ⁿ", "example": "A 1024 Hz clock into a 10-stage counter: 1024 ÷ 2¹⁰ = 1 Hz at the last output. A 4-stage counter counts 0 to 2⁴ − 1 = 15, then rolls back to 0.", "refs": [{"book": "bishop", "ch": 22, "page": 185}, {"book": "gibilisco", "ch": 30, "page": 566}]},
  {"unit": 4, "title": "Shift registers", "body": "A shift register is a chain of D flip-flops sharing one clock; at each clock edge every bit moves one place along. Data can go in or out one bit at a time (serial) or all at once (parallel), so shift registers convert between serial and parallel form, store data and create delays.", "formula": "Types: SISO, SIPO, PISO, PIPO;  delay = n stages × clock period", "example": "Shifting 1011 serially into an empty 4-bit SIPO register takes 4 clock pulses; after that all 4 bits can be read at once. At 1 MHz that takes 4 × 1 μs = 4 μs.", "refs": [{"book": "bishop", "ch": 22, "page": 190}, {"book": "gibilisco", "ch": 30, "page": 567}]},
  {"unit": 4, "title": "Digital-to-analogue converters", "body": "A digital-to-analogue converter (DAC) turns a binary number into a proportional voltage or current. Each bit is weighted by its place value, using binary-weighted resistors or an R-2R ladder feeding an op-amp, and the parts are summed. The smallest step, set by the LSB, is the resolution.", "formula": "Vout = step × N;   full scale = step × (2ⁿ − 1)", "example": "8-bit DAC, 10 mV steps: full scale = 255 × 10 mV = 2.55 V. Input 11001000₂ = 200 gives 200 × 10 mV = 2.00 V. Resolution = 10 ÷ 2550 × 100 ≈ 0.39%.", "refs": [{"book": "hughes", "ch": 24, "page": 491}, {"book": "bishop", "ch": 24, "page": 207}]},
  {"unit": 4, "title": "Analogue-to-digital converters", "body": "An analogue-to-digital converter (ADC) measures a voltage and outputs the nearest binary code. A flash ADC uses one comparator per level and is fastest. A successive-approximation ADC tries each bit from the MSB down, keeping it if its internal DAC is still below the input. Rounding to a step causes quantization error.", "formula": "Code ≈ Vin ÷ LSB size;  SAR ADC needs n clock cycles for n bits", "example": "4-bit SAR, 1 V steps, Vin = 9.3 V: try 1000 (8 V, below, keep), 1100 (12 V, too high, drop), 1010 (10 V, drop), 1001 (9 V, keep). Result 1001 = 9 after 4 clocks; error 0.3 V.", "refs": [{"book": "hughes", "ch": 24, "page": 499}, {"book": "bishop", "ch": 24, "page": 203}]},
  {"unit": 4, "title": "Integrated circuits: SSI to VLSI", "body": "An integrated circuit puts transistors, resistors and their wiring on one silicon chip. As processes improved, chips grew from small-scale integration (a few gates) through medium and large scale to very-large-scale integration (VLSI) with millions of transistors. Shorter on-chip wiring also means faster signals.", "formula": "Rough scale: SSI few gates, MSI 10–100, LSI 100–1000, VLSI more", "example": "A 7400 with 4 NAND gates is SSI; a 4-bit adder like the 74LS283 is MSI. A chip of 400 million transistors at 4 per NAND gate equals about 100 million gates: VLSI.", "refs": [{"book": "bishop", "ch": 25, "page": 211}, {"book": "gibilisco", "ch": 28, "page": 529}]},
  {"unit": 4, "title": "Memory: RAM, ROM and flash", "body": "RAM is read/write working memory: SRAM stores each bit in a flip-flop (fast, no refresh), DRAM stores it as charge that must be refreshed. RAM is volatile, so data is lost at power-off. ROM holds fixed programs; EEPROM and flash can be erased electrically and keep data without power.", "formula": "n address lines → 2ⁿ locations;  capacity = 2ⁿ × word width", "example": "A RAM with 13 address lines and 8 data lines has 2¹³ = 8192 locations × 8 bits = 65 536 bits (64 kbit = 8 kB). One more address line doubles it to 16 kB.", "refs": [{"book": "gibilisco", "ch": 28, "page": 530}, {"book": "bishop", "ch": 22, "page": 193}]},
  {"unit": 4, "title": "The microprocessor", "body": "A microprocessor is a VLSI chip that fetches binary instructions from memory and runs them in turn, timed by a clock. A control unit decodes instructions, an ALU does arithmetic and logic, and registers (accumulator, program counter) hold working values. It reaches memory and I/O over data, address and control buses.", "formula": "Address bus of n bits → 2ⁿ addressable locations;  1 byte = 8 bits", "example": "A CPU with a 16-bit address bus can reach 2¹⁶ = 65 536 locations (64 kB). With a 16 MHz clock, one clock cycle lasts 1 ÷ 16 MHz = 62.5 ns.", "refs": [{"book": "hughes", "ch": 27, "page": 559}, {"book": "bishop", "ch": 37, "page": 304}]},
  {"unit": 5, "title": "Moving-coil meters", "body": "A moving-coil (D'Arsonval) meter hangs a light coil between the poles of a permanent magnet. Current in the coil makes a turning force; hairsprings push back, so the pointer stops where the two balance. Deflection is proportional to current, giving an even scale, but it only reads DC.", "formula": "Deflection θ = (k ÷ c) × I  → pointer angle ∝ coil current", "example": "A meter swings 90° at its full-scale current of 1 mA. A current of 0.4 mA gives 0.4 × 90° = 36°, i.e. 40% of full scale. Reverse the current and the needle tries to swing below zero.", "refs": [{"book": "gibilisco", "ch": 3, "page": 48}, {"book": "hughes", "ch": 47, "page": 958}]},
  {"unit": 5, "title": "Ammeters and shunts", "body": "A meter movement reaches full scale at only a tiny current. To read bigger currents, a low-value shunt resistor is placed in parallel so most of the current bypasses the coil. An ammeter goes in series with the circuit and must have very low resistance.", "formula": "R_shunt = I_m × R_m ÷ (I − I_m)", "example": "Movement: 1 mA full scale, R_m = 100 Ω. For a 1 A range: V across coil = 0.001 × 100 = 0.1 V; shunt carries 0.999 A, so R_shunt = 0.1 ÷ 0.999 ≈ 0.1 Ω.", "refs": [{"book": "gibilisco", "ch": 3, "page": 49}, {"book": "hughes", "ch": 47, "page": 959}]},
  {"unit": 5, "title": "Voltmeters, multipliers, loading", "body": "A voltmeter is a current meter with a big series resistor (a multiplier), connected across the points being measured. It always draws a little current, so it disturbs the circuit (loading). The higher its resistance compared with the circuit, the truer the reading.", "formula": "R_series = V_FS ÷ I_FSD − R_m;  want R_meter ≫ R_circuit", "example": "50 µA, 1 kΩ movement, 10 V range: 10 ÷ 50 µA = 200 kΩ, so add 199 kΩ. Put it across one 100 kΩ of a 100k+100k divider on 10 V: 100k ∥ 200k = 66.7k, so it reads 4 V, not 5 V.", "refs": [{"book": "gibilisco", "ch": 3, "page": 50}, {"book": "hughes", "ch": 47, "page": 970}]},
  {"unit": 5, "title": "Ohmmeters and multimeters", "body": "An ohmmeter puts a battery and resistors in series with a meter; the unknown resistor sets the current. Zero ohms gives full scale and an open circuit gives zero, so the scale runs backwards and bunches up at high values. Always measure with the circuit unpowered. A multimeter combines V, I and Ω.", "formula": "I = V_batt ÷ (R_int + R_x);  half scale when R_x = R_int", "example": "1.5 V battery, 1 mA meter, R_int = 1.5 kΩ. R_x = 0 → 1 mA (full scale). R_x = 1.5 kΩ → 1.5 ÷ 3000 = 0.5 mA (half). R_x = 4.5 kΩ → 1.5 ÷ 6000 = 0.25 mA.", "refs": [{"book": "gibilisco", "ch": 3, "page": 51}, {"book": "gibilisco", "ch": 3, "page": 53}]},
  {"unit": 5, "title": "Digital meters", "body": "A digital voltmeter turns the input voltage into a number with an analog-to-digital converter and shows it as digits. There's no needle to misread, and its very high input resistance barely loads the circuit. The smallest step it can resolve sets the last-digit error.", "formula": "Count = V_in ÷ step size;  error ≤ ±1 step (1 count)", "example": "A ramp-type DVM with 10 mV steps counts up until its internal voltage just passes the input. For 5.123 V it stops at 513 steps and shows 5.13 V, at most 10 mV high.", "refs": [{"book": "hughes", "ch": 46, "page": 937}, {"book": "gibilisco", "ch": 3, "page": 56}]},
  {"unit": 5, "title": "The oscilloscope", "body": "An oscilloscope draws voltage (up) against time (across), so you can see a waveform's shape, size and timing. Read heights using the volts/div setting and widths using the time/div setting. It reads peak-to-peak directly and has a high input resistance (about 1 MΩ).", "formula": "V = divisions × V/div;  T = divisions × time/div;  f = 1 ÷ T", "example": "At 2 V/div a sine wave is 3.5 div tall: 7 V peak-to-peak, so V_rms = 7 ÷ 2√2 ≈ 2.47 V. One cycle spans 4 div at 0.5 ms/div: T = 2 ms, so f = 500 Hz.", "refs": [{"book": "hughes", "ch": 46, "page": 943}, {"book": "hughes", "ch": 46, "page": 948}]},
  {"unit": 5, "title": "The Wheatstone bridge", "body": "A Wheatstone bridge is four resistors in a diamond with a sensitive detector across the middle. You adjust a known resistor until the detector reads zero; then the two sides divide the voltage in the same ratio. Because it compares resistors at null, it is very accurate.", "formula": "At balance (no detector current): X = R × Q ÷ P", "example": "Ratio arms P = 100 Ω and Q = 1000 Ω. The detector nulls when the variable arm R = 352 Ω, so X = 352 × 1000 ÷ 100 = 3520 Ω.", "refs": [{"book": "hughes", "ch": 47, "page": 965}]},
  {"unit": 5, "title": "Instrumentation systems and sensors", "body": "A measuring system has three stages: a sensor turns a physical quantity (heat, light, force) into an electrical signal, processing amplifies and filters it, and a display shows it. Good sensors are selective, sensitive, linear, stable and fast.", "formula": "Sensor → signal processing → display", "example": "A thermocouple gives about 40 µV/°C. Hot junction 250 °C, cold junction 25 °C: ΔT = 225 °C → 225 × 40 µV = 9 mV. An amplifier with gain 100 lifts this to 0.9 V for the display.", "refs": [{"book": "bishop", "ch": 32, "page": 269}, {"book": "bishop", "ch": 32, "page": 271}]},
  {"unit": 5, "title": "Finding faults in systems", "body": "Fault-finding is a method, not guesswork. First state exactly what the system does wrong and when, then inspect for obvious damage, then check the power supply, then trace the signal stage by stage until you find where it goes wrong.", "formula": "Describe → inspect → check supplies → trace stage by stage", "example": "A 5 V board shows only 3.1 V at its IC supply pins. An ammeter in the supply line reads 900 mA against an expected 60 mA, 15× too much, pointing to a short (e.g. a solder bridge) from 5 V to 0 V.", "refs": [{"book": "bishop", "ch": 35, "page": 289}, {"book": "bishop", "ch": 35, "page": 290}]},
  {"unit": 5, "title": "Four-wire (Kelvin) measurement", "body": "When measuring small resistances, the test leads' own resistance gets in the way. Force current through one pair of wires and sense voltage with a separate pair that carries almost no current.", "formula": "R = V_sense / I_force   (lead resistance drops out)", "example": "ATE parametric units use force/sense (Kelvin) connections for precise DC measurements at the DUT pin.", "refs": []},
  {"unit": 5, "title": "Continuity (open/short) test", "body": "The first test in most chip programs. Each pin has protection diodes to the supply rails; forcing a small current and measuring the diode drop (≈0.6 V) proves the pin is connected — not open, not shorted.", "formula": "Typical: force −100 µA, expect about −0.2 to −0.9 V", "example": "Reading ~0 V suggests a short; hitting the voltage clamp suggests an open (bad contact or bond wire).", "refs": []},
  {"unit": 5, "title": "Input leakage (IIL / IIH)", "body": "An input should draw almost no current. Leakage tests force the pin low (IIL) and high (IIH) and check the current stays within limits — often under ±1 µA.", "formula": "Pass if |I_leak| ≤ spec (e.g. 1 µA)", "example": "High leakage can point to damaged gate oxide or ESD damage, even when the chip still works functionally.", "refs": []},
  {"unit": 5, "title": "IDDQ testing", "body": "A healthy CMOS chip draws only tiny current when idle. IDDQ tests stop the clock in known states and measure supply current; an unusually high reading reveals defects that functional tests miss.", "formula": "Fail if I_DDQ > limit (often µA–mA, depending on the chip)", "example": "A bridging defect between two wires can show up only as extra quiescent current.", "refs": []},
  {"unit": 5, "title": "Functional test vectors", "body": "A functional test applies a sequence of input patterns (vectors) at speed and compares each output with the expected value at a strobe time. Each pass/fail is decided per pin, per cycle.", "formula": "Expected 'H'/'L' compared at the strobe edge", "example": "On the V93000, patterns plus timing and level specs make up a functional test.", "refs": []},
  {"unit": 5, "title": "Shmoo plots", "body": "A shmoo plot sweeps two conditions — usually supply voltage and clock period — and marks pass/fail at each point. It shows how much margin a chip really has.", "formula": "X axis: period/frequency · Y axis: VDD · cells: pass/fail", "example": "A 'wall' of failures at high frequency and low voltage is normal; holes inside the pass region point to a real problem.", "refs": []},
];

// Which lesson is today's (1-based day number) — never beyond the course length.
export function dayNumber(todayISO) {
  const [y, m, d] = COURSE_START.split("-").map(Number);
  const [ty, tm, td] = todayISO.split("-").map(Number);
  const days = Math.round((Date.UTC(ty, tm - 1, td) - Date.UTC(y, m - 1, d)) / 86400000);
  return Math.max(1, days + 1);
}
